mapper.select:
select  from zjudg_master_withdraw w
left join zjudg_master m on m.master_id=w.master_id
where w.withdraw_id=#{withdrawId}

select from zjudg_master_withdraw w left join zjudg_master m on m.master_id=w.master_id
and w.withdraw_no like concat('%',#{withdrawNo},'%') and w.master_id=#{masterId} and m.master_name like concat('%',#{masterName},'%') and w.withdraw_status=#{withdrawStatus}
order by w.create_time desc
